#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

/**
 * Problem: 23771 - Lexicographic Order
 * 
 * 解題思路：
 * 1. 給定一個字串 S（包含 n 個不同字母）和它是第 k 個字典序排列。
 * 2. 尋找這 n 個字母的原始排序（即字典順序）。
 * 3. 這是「從排列與排名推導原始順序」的問題。
 * 4. 對於 n 個字母的排列，第一個位置的字母決定了它屬於哪一個 (n-1)! 的分組。
 * 5. 如果第一個字母是原始順序中的第 i 小，那麼它對應的排名範圍是 [(i-1)*(n-1)! + 1, i*(n-1)!]。
 * 6. 因此，我們可以計算每個字母在當時剩餘字母中的相對排名：
 *    - rank = (k-1) / (n-1)!
 *    - 更新 k = (k-1) % (n-1)! + 1
 * 7. 得到每個位置字母的相對排名後，我們可推導出每個字母在原始順序中的絕對位置。
 */

long long factorial[21];

void solve(int t) {
    string s;
    long long k;
    cin >> s >> k;
    int n = s.length();

    vector<int> relative_ranks(n);
    long long temp_k = k;
    for (int i = 0; i < n; i++) {
        long long f = factorial[n - 1 - i];
        relative_ranks[i] = (temp_k - 1) / f;
        temp_k = (temp_k - 1) % f + 1;
    }

    vector<int> positions(n); 
    vector<int> available;
    for (int i = 0; i < n; i++) available.push_back(i);

    for (int i = 0; i < n; i++) {
        int r = relative_ranks[i];
        positions[i] = available[r];
        available.erase(available.begin() + r);
    }

    string res = s;
    for (int i = 0; i < n; i++) {
        res[positions[i]] = s[i];
    }

    cout << "Case " << t << ": " << res << endl;
}

int main() {
    factorial[0] = 1;
    for (int i = 1; i <= 20; i++) factorial[i] = factorial[i - 1] * i;

    int t;
    if (cin >> t) {
        for (int i = 1; i <= t; i++) solve(i);
    }
    return 0;
}
